#!/usr/bin/env node
/**
 * Render deterministic RGBA PNG badges for Hugo's avatar icon pipeline from the
 * canonical two-bean Doubak geometry in doubak-website/assets/logos/gen_logo.py.
 *
 * Usage:
 *   node tools/assets/generate-badges.mjs          # write theme/hugo/assets/branding/doubak-badge-*.png
 *   node tools/assets/generate-badges.mjs --check  # verify committed PNGs match generated bytes
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { deflateSync } from 'node:zlib';

const GREEN = [46, 150, 61];
const BEAN = [255, 244, 216];
const SEGMENTS = [
  [[0, -5.2], [2.3, -5.2], [4, -2.9], [4, 0]],
  [[4, 0], [4, 2.9], [2.3, 5.2], [0, 5.2]],
  [[0, 5.2], [-2.1, 5.2], [-3.6, 3], [-3.6, 0.1]],
  [[-3.6, 0.1], [-3.6, -2.8], [-2.1, -5.2], [0, -5.2]],
];
const ROT = -20 * Math.PI / 180;
const BACK_SCALE = 1.00;
const FRONT_SCALE = 1.12;
const DIST = 7.6;
const AXIS = 41 * Math.PI / 180;
const HILUM_X = -2.8;
const HILUM_W = 1.15;
const HILUM_H = 3.9;
const RADIUS_PCT = 0.25;
const SUPERSAMPLE = 16;

export const BADGE_SPECS = Object.freeze([
  // 8px micro tier drops the sub-half-pixel front hilum and widens the channel so both ovals read cleanly.
  { size: 8, gap: 0.68, fillFrac: 0.72, hilums: 'none', maxCornerAlpha: 96 },
  // 12px matches doubak-icon-small.svg (16px base: gap=1.0, fill_frac=0.70, front hilum only).
  { size: 12, gap: 1.0 * 12 / 16, fillFrac: 0.70, hilums: 'front', maxCornerAlpha: 16 },
  // 36px matches doubak-icon-mid.svg (24px base: gap=0.95, fill_frac=0.66, hilums on both beans, no 豆 below 128px).
  { size: 36, gap: 0.95 * 36 / 24, fillFrac: 0.66, hilums: 'both', maxCornerAlpha: 1 },
]);

const POLY = (() => {
  const pts = [];
  for (const [p0, p1, p2, p3] of SEGMENTS) {
    for (let i = 0; i < 48; i++) {
      const t = i / 48;
      const u = 1 - t;
      pts.push([
        u ** 3 * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t ** 3 * p3[0],
        u ** 3 * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t ** 3 * p3[1],
      ]);
    }
  }
  return pts;
})();

const EDGES = POLY.map((p, i) => [p, POLY[(i + 1) % POLY.length]]);

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    table[i] = c;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function encodePng(size, rgba) {
  const chunk = (tag, data) => {
    const body = Buffer.concat([Buffer.from(tag), data]);
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length, 0);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body), 0);
    return Buffer.concat([len, body, crc]);
  };
  const raw = Buffer.alloc(size * (1 + size * 4));
  for (let y = 0; y < size; y++) {
    const off = y * (1 + size * 4);
    raw[off] = 0;
    rgba.copy(raw, off + 1, y * size * 4, (y + 1) * size * 4);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function inPoly(px, py) {
  if (px < -3.65 || px > 4.05 || py < -5.25 || py > 5.25) return false;
  let inside = false;
  for (const [[x1, y1], [x2, y2]] of EDGES) {
    if ((y1 > py) !== (y2 > py)) {
      const xi = (x2 - x1) * (py - y1) / (y2 - y1) + x1;
      if (px < xi) inside = !inside;
    }
  }
  return inside;
}

function inRoundedRect(x, y, w, h, r) {
  const cx = Math.min(Math.max(x, r), w - r);
  const cy = Math.min(Math.max(y, r), h - r);
  return (x - cx) ** 2 + (y - cy) ** 2 <= r * r;
}

const inHilum = (x, y) => inRoundedRect(x - HILUM_X, y + HILUM_H / 2, HILUM_W, HILUM_H, HILUM_W / 2);

/** Render a single Doubak badge PNG buffer for the given spec. */
export function renderBadgePng({ size, gap, fillFrac, hilums }) {
  const ca = Math.cos(ROT);
  const sa = Math.sin(ROT);
  const b = [0, 0];
  const f = [DIST * Math.cos(AXIS), DIST * Math.sin(AXIS)];

  const bboxPts = [];
  for (const [c, s] of [[b, BACK_SCALE], [f, FRONT_SCALE]]) {
    for (const [x0, y0] of POLY) {
      const x = x0 * s;
      const y = y0 * s;
      bboxPts.push([c[0] + x * ca - y * sa, c[1] + x * sa + y * ca]);
    }
  }
  const minx = Math.min(...bboxPts.map((p) => p[0]));
  const maxx = Math.max(...bboxPts.map((p) => p[0]));
  const miny = Math.min(...bboxPts.map((p) => p[1]));
  const maxy = Math.max(...bboxPts.map((p) => p[1]));
  const k = size * fillFrac / Math.max(maxx - minx, maxy - miny);
  const ox = size / 2 - (minx + maxx) / 2 * k;
  const oy = size / 2 - (miny + maxy) / 2 * k;

  const bx0 = ox + b[0] * k;
  const by0 = oy + b[1] * k;
  const fx0 = ox + f[0] * k;
  const fy0 = oy + f[1] * k;
  const bs = BACK_SCALE * k;
  const fs = FRONT_SCALE * k;
  const haloR = gap / fs;
  const haloR2 = haloR * haloR;
  const rTile = size * RADIUS_PCT;
  const invCa = Math.cos(-ROT);
  const invSa = Math.sin(-ROT);
  const showFrontHilum = hilums === 'front' || hilums === 'both';
  const showBackHilum = hilums === 'both';

  const inHalo = (lx, ly) => {
    if (lx < -3.65 - haloR || lx > 4.05 + haloR || ly < -5.25 - haloR || ly > 5.25 + haloR) return false;
    if (inPoly(lx, ly)) return true;
    for (const [[x1, y1], [x2, y2]] of EDGES) {
      const dx = x2 - x1;
      const dy = y2 - y1;
      const l2 = dx * dx + dy * dy;
      const t = Math.max(0, Math.min(1, ((lx - x1) * dx + (ly - y1) * dy) / l2));
      if ((lx - (x1 + t * dx)) ** 2 + (ly - (y1 + t * dy)) ** 2 <= haloR2) return true;
    }
    return false;
  };

  const out = Buffer.alloc(size * size * 4);
  const samples = SUPERSAMPLE * SUPERSAMPLE;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      let ar = 0;
      let ag = 0;
      let ab = 0;
      let aa = 0;
      for (let sy = 0; sy < SUPERSAMPLE; sy++) {
        const py = y + (sy + 0.5) / SUPERSAMPLE;
        for (let sx = 0; sx < SUPERSAMPLE; sx++) {
          const px = x + (sx + 0.5) / SUPERSAMPLE;
          if (!inRoundedRect(px, py, size, size, rTile)) continue;
          aa++;
          const fdx = (px - fx0) / fs;
          const fdy = (py - fy0) / fs;
          const flx = fdx * invCa - fdy * invSa;
          const fly = fdx * invSa + fdy * invCa;
          let col = GREEN;
          if (inPoly(flx, fly)) {
            if (!showFrontHilum || !inHilum(flx, fly)) col = BEAN;
          } else if (!inHalo(flx, fly)) {
            const bdx = (px - bx0) / bs;
            const bdy = (py - by0) / bs;
            const blx = bdx * invCa - bdy * invSa;
            const bly = bdx * invSa + bdy * invCa;
            if (inPoly(blx, bly) && (!showBackHilum || !inHilum(blx, bly))) col = BEAN;
          }
          ar += col[0];
          ag += col[1];
          ab += col[2];
        }
      }
      if (aa === 0) continue;
      const idx = (y * size + x) * 4;
      out[idx] = Math.round(ar / aa);
      out[idx + 1] = Math.round(ag / aa);
      out[idx + 2] = Math.round(ab / aa);
      out[idx + 3] = Math.round(aa / samples * 255);
    }
  }
  return encodePng(size, out);
}

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** Compare or write all committed badge PNGs under theme/hugo/assets/branding/. */
export function run({ check = false, root = ROOT } = {}) {
  const outDir = join(root, 'theme', 'hugo', 'assets', 'branding');
  const mismatches = [];
  for (const spec of BADGE_SPECS) {
    const file = join(outDir, `doubak-badge-${spec.size}.png`);
    const expected = renderBadgePng(spec);
    if (check) {
      let actual = null;
      try { actual = readFileSync(file); } catch {}
      if (!actual || !actual.equals(expected)) mismatches.push(file);
    } else {
      writeFileSync(file, expected);
    }
  }
  return mismatches;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const mismatches = run({ check });
  if (check) {
    if (mismatches.length) {
      console.error('角标 PNG 与矢量几何不一致：\n' + mismatches.join('\n'));
      process.exit(1);
    }
    console.log(`角标 PNG 一致（${BADGE_SPECS.map((s) => `${s.size}px`).join(' / ')}）。`);
  } else {
    console.log(`已生成 ${BADGE_SPECS.map((s) => `doubak-badge-${s.size}.png`).join('、')}。`);
  }
}
